CREATE TABLE el_zero_payroll_closures(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,teacher_payroll_id TEXT,staff_payroll_id TEXT,closed_by TEXT NOT NULL,closed_on TEXT NOT NULL,reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 5 AND 1000),created_at INTEGER NOT NULL,CHECK((teacher_payroll_id IS NOT NULL AND staff_payroll_id IS NULL) OR (staff_payroll_id IS NOT NULL AND teacher_payroll_id IS NULL)),UNIQUE(org_id,teacher_payroll_id),UNIQUE(org_id,staff_payroll_id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,teacher_payroll_id) REFERENCES el_payroll(org_id,id),FOREIGN KEY(org_id,staff_payroll_id) REFERENCES el_staff_payroll(org_id,id),FOREIGN KEY(org_id,closed_by) REFERENCES el_memberships(org_id,user_id));
CREATE INDEX el_zero_payroll_closures_branch ON el_zero_payroll_closures(org_id,branch_id,closed_on);
CREATE TRIGGER el_zero_payroll_closure_guard BEFORE INSERT ON el_zero_payroll_closures BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_memberships m JOIN el_role_permissions rp ON rp.role_id=m.role_id AND rp.resource='finance' AND rp.action='approve' WHERE m.org_id=NEW.org_id AND m.user_id=NEW.closed_by AND m.status='active' AND (m.branch_id IS NULL OR m.branch_id=NEW.branch_id)) THEN RAISE(ABORT,'Zero payroll closure needs scoped finance approval') END;
 SELECT CASE WHEN NEW.teacher_payroll_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM el_payroll p WHERE p.id=NEW.teacher_payroll_id AND p.org_id=NEW.org_id AND p.branch_id=NEW.branch_id AND p.status='approved' AND p.total=0 AND p.journal_id IS NULL AND p.approved_by IS NOT NULL AND p.created_by<>NEW.closed_by AND p.approved_by<>NEW.closed_by AND NEW.closed_on>=date(p.month||'-01','+1 month','-1 day')) THEN RAISE(ABORT,'Only independently approved zero payroll can close without payment') END;
 SELECT CASE WHEN NEW.staff_payroll_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM el_staff_payroll p WHERE p.id=NEW.staff_payroll_id AND p.org_id=NEW.org_id AND p.branch_id=NEW.branch_id AND p.status='approved' AND p.total=0 AND p.accrual_journal_id IS NULL AND p.payment_journal_id IS NULL AND p.approved_by IS NOT NULL AND p.created_by<>NEW.closed_by AND p.approved_by<>NEW.closed_by AND NEW.closed_on>=date(p.month||'-01','+1 month','-1 day')) THEN RAISE(ABORT,'Only independently approved zero employee payroll can close without payment') END;
END;
CREATE TRIGGER el_zero_payroll_closure_immutable BEFORE UPDATE ON el_zero_payroll_closures BEGIN SELECT RAISE(ABORT,'Zero payroll closure is immutable'); END;
CREATE TRIGGER el_zero_payroll_closure_no_delete BEFORE DELETE ON el_zero_payroll_closures BEGIN SELECT RAISE(ABORT,'Zero payroll closure is immutable'); END;
CREATE TRIGGER el_payroll_zero_no_payment BEFORE UPDATE OF status ON el_payroll WHEN NEW.status='paid' AND (NEW.total=0 OR EXISTS(SELECT 1 FROM el_zero_payroll_closures WHERE teacher_payroll_id=OLD.id AND org_id=OLD.org_id)) BEGIN SELECT RAISE(ABORT,'Zero payroll must close without payment'); END;
CREATE TRIGGER el_staff_payroll_zero_no_payment BEFORE UPDATE OF status ON el_staff_payroll WHEN NEW.status='paid' AND (NEW.total=0 OR EXISTS(SELECT 1 FROM el_zero_payroll_closures WHERE staff_payroll_id=OLD.id AND org_id=OLD.org_id)) BEGIN SELECT RAISE(ABORT,'Zero employee payroll must close without payment'); END;
